async(page)=>{
 const base='http://127.0.0.1:5173/',checks=[],metrics=[],errors=[],cloudCalls=[],onError=e=>errors.push(e.message),onRequest=r=>{if(/cloudbasegateway|tencentcloudapi|tcb-api/.test(r.url()))cloudCalls.push(r.url())}
 page.on('pageerror',onError);page.on('request',onRequest);let failure=''
 const routes=[['','同乡今天吃什么。'],['blindbox','开盲盒 · 今天吃点啥'],['treehole?tab=black','黑榜 · 避雷参考'],['me','示例管理员'],['detail/demo-food-1','黄焖鸡'],['publish/demo-food-1','补充这张饭票'],['onboarding','完善资料'],['onboarding?preferences=1','我的口味偏好'],['admin','用户治理'],['user/demo-profile-demo-other','阿岚同学'],['feedback','用户反馈'],['blocked','账号状态与申诉'],['messages','互动消息'],['tree-detail/demo-caution-2','示例店铺 B'],['tree-compose/demo-caution-2','写消费经历'],['tree-admin','避雷经历 · 审核与举报'],['treehole?tab=forum','同乡聊聊 · 留言广场'],['forum/demo-forum-topic-1','云南同乡今天吃什么？'],['forum-compose','写一条树洞留言'],['forum-admin','讨论治理']]
 try{
  for(const width of [320,390,1440]){await page.setViewportSize({width,height:900});for(const [route,title]of routes){await page.goto(base+'?pages='+width+'-'+encodeURIComponent(route)+'&demo=admin#/'+route);await page.getByRole('heading',{name:title,exact:true}).first().waitFor();const m=await page.locator('.app-frame').evaluate(e=>{const r=e.getBoundingClientRect();return {center:Math.abs((r.left+r.right)/2-innerWidth/2),overflow:e.scrollWidth>e.clientWidth+1||document.documentElement.scrollWidth>innerWidth+1}});if(m.overflow||m.center>=1)throw Error('页面居中/溢出 '+width+' '+route);checks.push('页面适配 '+width+' '+route);metrics.push({width,route,...m})}}
  await page.goto(base+'?pages=switch&demo=admin#/');await page.getByRole('heading',{name:'同乡今天吃什么。',exact:true}).waitFor();const changes=await page.evaluate(async()=>{let fullLoader=false,frames=0;const watch=new MutationObserver(()=>{frames++;if(document.body.innerText.includes('正在加载小食云记…'))fullLoader=true});watch.observe(document.querySelector('#root'),{childList:true,subtree:true});for(const route of ['/me','/blindbox','/treehole?tab=forum','/me','/']){location.hash=route;await new Promise(r=>setTimeout(r,150))}watch.disconnect();return {fullLoader,frames}});if(changes.fullLoader||!changes.frames)throw Error('切页出现整屏初始化等待');checks.push('初始化后切换各主页面不重复出现整屏加载')
  await page.waitForFunction(()=>[...document.images].every(i=>!i.getAttribute('src')||i.complete));const broken=await page.locator('img').evaluateAll(rows=>rows.filter(i=>i.getAttribute('src')&&i.complete&&!i.naturalWidth).map(i=>i.getAttribute('src')));if(broken.length)throw Error('公开页面图片路径失效：'+broken.join(','));checks.push('页面图标和封面路径可加载')
  if(errors.length||cloudCalls.length)throw Error('页面异常或演示访问真实后端');checks.push('全部页面演示不访问云端且无运行时错误')
 }catch(e){failure=e.message}
 page.off('pageerror',onError);page.off('request',onRequest);return {base,checks,metrics,errors,cloudCalls,failure}
}
